(6141323, 905059, 81362, '<td valign="top">Yellow flowers make a good irregular compliment to the yellow hull. Wonder if a more dynamic result could have come from stepping to the side to make the boat less centered and the edge of the water more diagonal.</td>', 'Yellow flowers make a good irregular compliment to the yellow hull. Wonder if a more dynamic result could have come from stepping to the side to make the boat less centered and the edge of the water more diagonal.', '2010-08-25 21:42:50.000000', NULL, 1),
(6141325, 904541, 81362, '<td valign="top">Pretty funny set up. Strong light from the side addes to the sense of an emotional gathering.</td>', 'Pretty funny set up. Strong light from the side addes to the sense of an emotional gathering.', '2010-08-25 21:44:05.000000', NULL, 1),
