(6141398, 904544, 81362, '<td valign="top">Had to crank my browser magnification up to 400% to see the yellow n the float. May not be enough on topic for most voters.</td>', 'Had to crank my browser magnification up to 400% to see the yellow n the float. May not be enough on topic for most voters.', '2010-08-25 22:46:51.000000', NULL, 1),
(6141404, 904327, 81362, '<td valign="top">Delicate with good preservation of detail. Yellow-green this pale may not fit preconceptions of the topic challenge.</td>', 'Delicate with good preservation of detail. Yellow-green this pale may not fit preconceptions of the topic challenge.', '2010-08-25 22:52:03.000000', NULL, 1),
(6141411, 905310, 81362, '<td valign="top">Interesting stack of fruit in unusual positions. I would expect lowish scores due to the harsh lighting. Might consider moving the objects closer on the reflective surface to get better shadows there, and moving the table further from the wall behind to remove the shadows directly behind the objects. Looks like on-camera flash, in a situation when moving it off camera or diffusing it might be improvements.</td>', 'Interesting stack of fruit in unusual positions. I would expect lowish scores due to the harsh lighting. Might consider moving the objects closer on the reflective surface to get better shadows there, and moving the table further from the wall behind to remove the shadows directly behind the objects. Looks like on-camera flash, in a situation when moving it off camera or diffusing it might be improvements.', '2010-08-25 22:56:24.000000', NULL, 1),
(6141412, 904677, 73942, '<td valign="top">very pretty, love this</td>', 'very pretty, love this', '2010-08-25 22:56:28.000000', NULL, 1),
(6141414, 905372, 81362, '<td valign="top">Nice pattern on the table surface. Wish the depth of focus could have included the slice inserted on the stemware rim.</td>', 'Nice pattern on the table surface. Wish the depth of focus could have included the slice inserted on the stemware rim.', '2010-08-25 22:57:53.000000', NULL, 1);
