(6142277, 905231, 86322, '<td valign="top">Irene, Irene, you dont cease me to amaze me with these kind of shots...if you are not Irene, please dont be upset, take it as a good complement. I dont care about what anybody says about water shots. This is a such a awesome photo, the tones, the lighting, the composition, the sharpness, the concept, the relation between the tranquility of the liquid, the splash and the "earth" sinking in a sea of oil is beautifully conceived... Shold be the winner of this challenge in my opinion. 10</td>', 'Irene, Irene, you dont cease me to amaze me with these kind of shots...if you are not Irene, please dont be upset, take it as a good complement. I dont care about what anybody says about water shots. This is a such a awesome photo, the tones, the lighting, the composition, the sharpness, the concept, the relation between the tranquility of the liquid, the splash and the "earth" sinking in a sea of oil is beautifully conceived... Shold be the winner of this challenge in my opinion. 10', '2010-08-26 20:48:48.000000', NULL, 1),
(6142278, 904851, 86322, '<td valign="top">Just beautiful shot, you cant even see the glass. 9</td>', 'Just beautiful shot, you cant even see the glass. 9', '2010-08-26 20:51:29.000000', NULL, 1),
